// Static asset — not regenerated by report.py, not counted in the Python
// budget (R-10 only measures backend/evals/minimal/*.py). Renders the page
// from window.REPORT_DATA, which report.py embeds inline (never fetch()'d —
// fetch() against file:// is blocked, so the data travels IN the page).
//
// Every number here (judge means, checks percentages, bands) was computed by
// Python's score.py before this ever ran — this file only sorts, routes and
// builds DOM. Two implementations of the same arithmetic (one Python, one JS)
// is exactly the class of bug this harness exists to catch, so this file
// computes none.
//
// Three "pages", one file, hash-routed:
//   #/                      index — every run
//   #/run/<id>              one run — its stage table
//   #/run/<id>/<stage>      one stage — its rows, judge detail, artifacts

(function () {
  "use strict";
  const DATA = window.REPORT_DATA;
  const BAND_HIGH = 90.0, BAND_MID = 70.0;
  const PALETTE = ["#2f6fdb", "#d97706", "#059669", "#db2777", "#7c3aed"];

  function escapeHtml(value) {
    return String(value).replace(/[&<>"']/g, (c) => (
      { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]
    ));
  }

  function band(value) {
    if (value === null || value === undefined) return "flat";
    if (value >= BAND_HIGH) return "high";
    if (value >= BAND_MID) return "mid";
    return "low";
  }

  function pill(text, cls) {
    return `<span class="pill ${cls}">${escapeHtml(text)}</span>`;
  }

  // ── sortable / searchable tables (client-side only — every value sorted
  // here was already computed by score.py; this never recomputes a number) ──

  function makeSortable(table) {
    const body = table.tBodies[0];
    Array.prototype.forEach.call(table.tHead.rows[0].cells, (th, index) => {
      th.classList.add("sortable");
      th.tabIndex = 0;
      const activate = () => {
        const dir = th.getAttribute("data-dir") === "asc" ? "desc" : "asc";
        Array.prototype.forEach.call(table.tHead.rows[0].cells, (other) => other.removeAttribute("data-dir"));
        th.setAttribute("data-dir", dir);
        const rows = Array.prototype.slice.call(body.rows);
        rows.sort((a, b) => {
          const av = a.cells[index].getAttribute("data-sort") ?? a.cells[index].textContent.trim();
          const bv = b.cells[index].getAttribute("data-sort") ?? b.cells[index].textContent.trim();
          const an = Number(av), bn = Number(bv);
          const cmp = (!isNaN(an) && !isNaN(bn) && av !== "" && bv !== "")
            ? an - bn : String(av).localeCompare(String(bv));
          return dir === "asc" ? cmp : -cmp;
        });
        rows.forEach((row) => body.appendChild(row));
      };
      th.addEventListener("click", activate);
      th.addEventListener("keydown", (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); activate(); } });
    });
  }

  function makeSearchable(input, table, countEl) {
    input.addEventListener("input", () => {
      const needle = input.value.trim().toLowerCase();
      let shown = 0;
      const rows = table.tBodies[0].rows;
      for (const row of rows) {
        const hay = (row.getAttribute("data-search") || row.textContent).toLowerCase();
        const match = !needle || hay.indexOf(needle) !== -1;
        row.classList.toggle("hidden", !match);
        if (match) shown++;
      }
      if (countEl) countEl.textContent = `showing ${shown} of ${rows.length}`;
    });
  }

  function findRun(runId) {
    return DATA.runs.find((r) => r.run_id === runId);
  }

  // Straight off Python's `run.totals` — this used to average the stages here
  // in JS, a second implementation of arithmetic score.py already owns (see
  // this file's header). Now the index row and the run page's footer are the
  // same numbers by construction rather than by coincidence.
  function runStats(run) {
    const t = run.totals || {};
    return {
      nStages: t.stages ?? 0,
      completed: t.completed ?? 0,
      total: t.total ?? 0,
      judgeMean: t.judge_mean ?? null,
      checksMean: t.checks_mean ?? null,
    };
  }

  // ── router ────────────────────────────────────────────────────────────

  function route() {
    const parts = location.hash.replace(/^#\/?/, "").split("/").filter(Boolean);
    if (parts[0] === "advise") {
      if (parts[1] && parts[2]) renderAdviceStage(decodeURIComponent(parts[1]), decodeURIComponent(parts[2]));
      else if (parts[1]) renderAdviceWorkflow(decodeURIComponent(parts[1]));
      else renderAdviceIndex();
    } else if (parts[0] === "run" && parts[1] && parts[2]) {
      renderStage(parts[1], decodeURIComponent(parts[2]));
    } else if (parts[0] === "run" && parts[1]) {
      renderRun(parts[1]);
    } else {
      renderIndex();
    }
    window.scrollTo(0, 0);
    markActiveTab();
  }

  function markActiveTab() {
    const onAdvice = /^#\/advise/.test(location.hash);
    for (const a of document.querySelectorAll(".tabs a")) {
      a.classList.toggle("active", (a.getAttribute("data-tab") === "advise") === onAdvice);
    }
  }
  window.addEventListener("hashchange", route);
  window.addEventListener("DOMContentLoaded", route);

  // ── theme toggle (bootstrap script in report.py's shell sets the initial
  // data-theme attribute before first paint, so there's no flash) ──────
  function currentTheme() {
    return document.documentElement.getAttribute("data-theme") ||
      (window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light");
  }
  window.addEventListener("DOMContentLoaded", () => {
    const toggle = document.getElementById("theme-toggle");
    if (!toggle) return;
    toggle.textContent = currentTheme() === "dark" ? "☀️" : "🌙";
    toggle.addEventListener("click", () => {
      const next = currentTheme() === "dark" ? "light" : "dark";
      document.documentElement.setAttribute("data-theme", next);
      toggle.textContent = next === "dark" ? "☀️" : "🌙";
      try { localStorage.setItem("eval-report-theme", next); } catch (e) { /* private mode */ }
    });
  });

  function mount(html) {
    document.getElementById("app").innerHTML = html;
  }

  function warningsHtml() {
    if (!DATA.warnings.length) return "";
    const items = DATA.warnings.map((w) => `<li>${escapeHtml(w)}</li>`).join("");
    return `<section class="card warn"><h2>Warnings</h2><ul>${items}</ul></section>`;
  }


  // Column glossary. These headers carry numbers whose meaning is NOT
  // self-evident — "checks n/a" and "judge 95 / checks 0" both need saying
  // out loud — so each one explains itself in place.
  const COLUMN_INFO = {
    run: "Run id: the UTC timestamp the run started, plus its dataset. Newest first.",
    stages: "How many pipeline stages this run has stored data for.",
    workflow: "Which workflow this run exercised, from its own config snapshot (`workflow:`, or the agent-id prefix for runs stored before workflows were declared). Not the dataset name — a dataset can be pointed at any pipeline.",
    dataset: "The dataset this run dispatched.",
    adviceStages: "Stages in this workflow that have at least one advisor proposal.",
    adviceUnique: "Distinct proposals after de-duplicating identical text across runs. A proposal seen in several runs is a standing gap in the prompt, not a one-off.",
    adviceTotal: "Advisor calls that returned a proposal, before de-duplication.",
    adviceCategory: "Rubric dimension the suggestion serves. Clustering on this — a closed vocabulary handed to the advisor — is what makes the same gap collapse into one bucket however it was worded.",
    stage: "The pipeline stage — one agent dispatch per row.",
    judge: "LLM judge score, 0-100, weighted across this rubric's dimensions. Content quality only: the judge reads the output as text and cannot tell whether it runs. Not a pass/fail.",
    judgeAvg: "Mean of the per-stage judge scores in this run. Stages never judged are excluded, not counted as zero.",
    checks: "Two independent checks. RENDER loads the page in headless Chromium and walks every nav link — ground truth. STATIC lints the source against a convention, so it can fail on a page that renders fine. 'n/a' means the stage emits prose, not HTML. Original: Deterministic checks: static_check (structure, routes, handlers) plus render_check (headless Chromium — does it load, do the nav links work). Free, and no model can flatter it. 'n/a' means the stage emits prose, not HTML, so there is nothing to check.",
    checksAvg: "Mean of the per-stage checks pass rates in this run. Stages with no HTML deliverable are excluded.",
    completed: "Rows that dispatched without erroring, over rows attempted.",
  };

  // `data-tip` drives a CSS tooltip rather than the native `title=`, which
  // has a long delay, never fires on touch, and cannot be reached by
  // keyboard. `title` stays as the no-CSS fallback.
  function info(key) {
    const text = COLUMN_INFO[key];
    if (!text) return "";
    const safe = escapeHtml(text);
    return ` <span class="info" tabindex="0" role="note" aria-label="${safe}" title="${safe}" data-tip="${safe}">i</span>`;
  }



  // A checks cell carries three different states that a bare number cannot
  // tell apart: not applicable (prose stage), passed, and failed-by-which-
  // half. `render` ran the page in Chromium; `static` only linted the source
  // against a convention, so a static-only failure can sit on a page that
  // works. Never present them as the same thing.
  function checksCell(checks) {
    if (!checks) return `${pill("n/a", "flat")}<div class="muted small">no HTML deliverable</div>`;
    const cell = pill(`${checks.pct.toFixed(1)} (n=${checks.n})`, band(checks.pct));
    const reasons = checks.reasons || [];        // render — these gate
    const advisories = checks.advisories || [];  // static lint — never gates

    // FAILED is said only about the gate. Saying "static failed" beside a
    // passing 100.0 was a straight contradiction: static stopped gating when
    // render became the verdict, and this cell kept the old wording.
    if (reasons.length) {
      const more = reasons.length > 1 ? ` (+${reasons.length - 1} more)` : "";
      return `${cell}<div class="fail-why" data-tip="${escapeHtml(reasons.join(" \u2022 "))}">` +
        `<strong>render failed</strong><span class="muted small"> — ${escapeHtml(reasons[0])}${more}</span></div>`;
    }
    if (advisories.length) {
      return `${cell}<div class="muted small" data-tip="${escapeHtml(advisories.join(" \u2022 "))}">` +
        `${advisories.length} static advisory — not gating</div>`;
    }
    return cell;
  }

  // The stage page's checks banner — the same verdict the run table shows,
  // with the reasons in full. Previously the run page said a stage failed and
  // the stage page said nothing, so the one screen you opened to find out why
  // was the one screen that would not tell you.
  function checksBanner(facts) {
    const c = facts.checks;
    if (!c) {
      return `<section class="card"><h2>Checks</h2>
        <p class="muted">n/a — this stage has no HTML deliverable, so there is nothing to check.
        Its judge score stands alone.</p></section>`;
    }
    const reasons = c.reasons || [];        // render — these gate
    const advisories = c.advisories || [];  // static lint — never gates
    const failed = reasons.length > 0;
    const list = (items, cls) => `<ul class="${cls}">` +
      items.map((r) => `<li>${escapeHtml(r)}</li>`).join("") + `</ul>`;

    const head = failed
      ? `<h2>Checks — FAILED <span class="pill low">${c.pct.toFixed(1)} (n=${c.n})</span></h2>
         <p class="muted small">The render check loaded this page in headless Chromium and walked
         every nav link. These are what it found.</p>${list(reasons, "why")}`
      : `<h2>Checks — passed <span class="pill high">${c.pct.toFixed(1)} (n=${c.n})</span></h2>
         <p class="muted small">Headless Chromium loaded the page and every nav link resolved.</p>`;

    const adv = advisories.length
      ? `<details class="advisory"><summary>${advisories.length} static advisory finding(s) — not gating</summary>
         <p class="muted small">static_check lints the SOURCE against one router convention and
         can flag valid alternatives, so it never fails the gate. Worth reading anyway: it sees
         things the render check cannot, such as a page no nav link points at.</p>
         ${list(advisories, "why muted")}</details>`
      : "";
    return `<section class="card ${failed ? "warn" : ""}">${head}${adv}</section>`;
  }

  // ── advice: workflow -> stage -> unique proposals ────────────────────
  // Counts come from Python (DATA.advice); this only renders them.

  function adviceData() { return DATA.advice || {}; }

  function renderAdviceIndex() {
    const wfs = Object.entries(adviceData());
    if (!wfs.length) {
      return mount(`<div class="hero"><h1>Advice</h1>
        <p class="sub">Nothing yet — advice is opt-in. Run with <code>--advise</code> to collect it.</p></div>`);
    }
    const rows = wfs.map(([wf, w]) => `<tr>
      <td data-sort="${escapeHtml(wf)}"><a href="#/advise/${encodeURIComponent(wf)}">${escapeHtml(wf)}</a></td>
      <td data-sort="${Object.keys(w.stages).length}">${Object.keys(w.stages).length}</td>
      <td data-sort="${w.unique}">${pill(String(w.unique), "flat")}</td>
      <td data-sort="${w.total}">${w.total}</td></tr>`).join("");
    mount(`<div class="hero"><h1>Advice</h1>
      <p class="sub">Prompt edits the advisor proposed, pooled across every run — a proposal that
      keeps reappearing is a standing gap, not a one-off.</p></div>
      <section class="card"><div class="tablewrap"><table id="advice-table">
      <thead><tr><th>workflow${info("workflow")}</th><th>stages${info("adviceStages")}</th>
      <th>unique advice${info("adviceUnique")}</th><th>total${info("adviceTotal")}</th></tr></thead>
      <tbody>${rows}</tbody></table></div></section>`);
    makeSortable(document.getElementById("advice-table"));
  }

  function renderAdviceWorkflow(workflow) {
    const w = adviceData()[workflow];
    if (!w) return mount(`<p class="crumbs"><a href="#/advise">Advice</a></p><p>no advice for ${escapeHtml(workflow)}</p>`);
    const rows = Object.entries(w.stages).map(([stage, st]) => {
      const cats = Object.entries(st.categories)
        .sort((a, b) => b[1].max_score - a[1].max_score)
        .map(([c, v]) => `<span class="pill ${v.max_score >= 70 ? "low" : "flat"}">${escapeHtml(c)} ${v.unique}</span>`)
        .join(" ");
      return `<tr>
        <td data-sort="${escapeHtml(stage)}"><a href="#/advise/${encodeURIComponent(workflow)}/${encodeURIComponent(stage)}">${escapeHtml(stage)}</a></td>
        <td data-sort="${st.unique}">${st.unique}</td>
        <td>${cats}</td></tr>`;
    }).join("");
    mount(`<p class="crumbs"><a href="#/advise">Advice</a> / ${escapeHtml(workflow)}</p>
      <h1>${escapeHtml(workflow)}</h1>
      <p class="muted" style="margin-top:-8px">${w.unique} unique suggestion(s) across ${w.total} advisor call(s)</p>
      <section class="card"><div class="tablewrap"><table id="advice-stage-table">
      <thead><tr><th>stage${info("stage")}</th><th>unique${info("adviceUnique")}</th>
      <th>categories${info("adviceCategory")}</th></tr></thead>
      <tbody>${rows}</tbody></table></div></section>`);
    makeSortable(document.getElementById("advice-stage-table"));
  }

  // 0-100 is not a grade here — it is how strongly the edit is advised.
  // Showing the bare number read as a score, which it is not.
  function must(score) {
    if (score >= 90) return `MUST (${score})`;
    if (score >= 60) return `SHOULD (${score})`;
    if (score >= 30) return `SHOULD NOT SKIP (${score})`;
    return `MAY (${score})`;
  }

  function renderAdviceStage(workflow, stage) {
    const st = ((adviceData()[workflow] || {}).stages || {})[stage];
    if (!st) return mount(`<p class="crumbs"><a href="#/advise">Advice</a></p><p>no advice for ${escapeHtml(stage)}</p>`);
    // Highest-priority category first: one MUST outranks several MAYs.
    const cats = Object.entries(st.categories).sort((a, b) => b[1].max_score - a[1].max_score);
    // SUPERSEDED advice is history, not a work list. It stays on the page —
    // it is the record of what was already asked for, and a suggestion that
    // reappears after being applied is worth seeing — but as a compact table
    // underneath, so the cards above are only the work that remains.
    // `unknown` sits with open: absence of a hash is not evidence of applied.
    const isOpen = (e) => e.prompt_state !== "superseded";
    const applied = cats.flatMap(([category, c]) =>
      c.entries.filter((e) => !isOpen(e)).map((e) => ({ ...e, _cat: e.category || category })));
    const blocks = cats.map(([category, c]) => {
      const open = c.entries.filter(isOpen);
      if (!open.length) return "";
      const items = open.map((e) => {
        // advisory_score is a MUST/MAY strength, not a quality score — label
        // it so, since a bare number here reads like the judge's 0-100.
        const strength = e.advisory_score >= 70 ? "MUST" : e.advisory_score >= 30 ? "SHOULD" : "MAY";
        const tone = e.advisory_score >= 70 ? "low" : e.advisory_score >= 30 ? "mid" : "flat";
        const act = e.action === "remove" ? "REMOVE" : "ADD";
        const seen = e.count > 1 ? `<span class="pill mid">seen ${e.count}x</span>` : "";
        // OPEN vs SUPERSEDED, inferred from the prompt hash the advice was
        // collected against versus the one that would dispatch today. Nothing
        // records that a suggestion was APPLIED — what is recorded is that the
        // prompt moved on, which covers both "you applied it" and "you wrote
        // past it". Python has already sorted open first; this says why.
        const state = e.prompt_state === "current"
          ? `<span class="pill low">OPEN</span>`
          : e.prompt_state === "superseded"
            ? `<span class="pill flat" data-tip="Collected against a prompt body that has since changed — applied, or made moot by the rewrite.">SUPERSEDED</span>`
            : "";
        const runs = [...new Set(e.runs)].map((r) =>
          `<a href="#/run/${encodeURIComponent(r)}/${encodeURIComponent(stage)}">${escapeHtml(r)}</a>`).join(", ");
        const why = (e.reasons || []).length
          ? `<div class="advice-reason"><span class="muted small">why:</span> ${escapeHtml(e.reasons.join(" · "))}</div>`
          : "";
        return `<li>
          <div class="advice-tags">
            <span class="pill ${e.action === "remove" ? "low" : "flat"}">${act}</span>
            <span class="pill ${tone}">${strength} ${e.advisory_score}</span>
            <span class="pill flat">${escapeHtml(e.category || category)}</span>
            ${seen}${state}
          </div>
          <div class="advice-desc">${escapeHtml(e.description)}</div>
          ${why}
          <div class="muted small">${runs}</div></li>`;
      }).join("");
      return `<section class="card">
        <h2>${escapeHtml(category)} <span class="muted small">— ${open.length} open, strongest: ${priority(c.max_score).label}</span></h2>
        <ul class="advice-list">${items}</ul></section>`;
    }).join("");

    const appliedRows = applied.map((e) => {
      const act = e.action === "remove" ? "REMOVE" : "ADD";
      const runs = [...new Set(e.runs)];
      const strength = e.advisory_score >= 70 ? "MUST" : e.advisory_score >= 30 ? "SHOULD" : "MAY";
      return `<tr>
        <td data-sort="${escapeHtml(act)}"><span class="pill flat">${act}</span></td>
        <td data-sort="${e.advisory_score}"><span class="pill flat">${strength} ${e.advisory_score}</span></td>
        <td data-sort="${escapeHtml(e.prompt_state || "")}"><span class="pill flat"
          data-tip="Collected against a prompt body that has since changed — applied, or made moot by the rewrite.">${
          e.prompt_state === "superseded" ? "APPLIED" : escapeHtml(e.prompt_state || "—")}</span></td>
        <td data-sort="${escapeHtml(e._cat)}">${escapeHtml(e._cat)}</td>
        <td>${escapeHtml(e.description)}</td>
        <td data-sort="${e.count}">${e.count}</td>
        <td data-sort="${escapeHtml(runs[0] || "")}" class="muted small">
          ${runs.map((r) => `<a href="#/run/${encodeURIComponent(r)}/${encodeURIComponent(stage)}">${escapeHtml(r)}</a>`).join(", ")}</td></tr>`;
    }).join("");

    const appliedCard = applied.length ? `<section class="card">
      <h2>Applied / superseded <span class="muted small">— ${applied.length}</span></h2>
      <p class="muted small">Collected against a prompt body that has since changed. Kept as the
      record of what was already asked for — if one of these reappears as OPEN in a later run, it
      was asked for, applied, and did not stick.</p>
      <div class="tablewrap"><table id="applied-table">
        <thead><tr><th>action</th><th>score</th><th>applied</th><th>category</th><th>suggestion</th><th>seen</th><th>runs</th></tr></thead>
        <tbody>${appliedRows}</tbody></table></div></section>` : "";
    mount(`<p class="crumbs"><a href="#/advise">Advice</a> /
      <a href="#/advise/${encodeURIComponent(workflow)}">${escapeHtml(workflow)}</a> / ${escapeHtml(stage)}</p>
      <h1>${escapeHtml(stage)}${st.agent_id ? ` <span class="muted small">${escapeHtml(st.agent_id)}</span>` : ""}</h1>
      ${(st.open || 0) < st.unique ? `<section class="card warn">
        <h2>${st.open || 0} of ${st.unique} still open</h2>
        <p class="muted small">The rest were collected against a prompt body that has since
        changed — applied, or made moot by the rewrite. Keyed on the open count, not the version
        count: a stage with ONE stored version is entirely superseded the moment the live prompt
        moves off it, which is exactly what an active override does.</p></section>` : ""}
      <p class="muted" style="margin-top:-8px">Grouped by rubric dimension, strongest first.
      MUST (≥70) / SHOULD (≥30) / MAY — how hard the advisor pushed, priced from what the
      weakness cost.</p>
      ${blocks || `<section class="card"><h2>Nothing open</h2>
        <p class="muted small">Every suggestion for this stage was collected against a prompt body
        that has since changed. Re-run the stage to collect advice against the current prompt.</p>
        </section>`}
      ${appliedCard}`);
    const appliedTable = document.getElementById("applied-table");
    if (appliedTable) makeSortable(appliedTable);
  }

  // ── index: every run ─────────────────────────────────────────────────

  function overviewHtml() {
    const allStages = DATA.runs.flatMap((r) => Object.values(r.stages));
    const judged = allStages.filter((s) => s.judge && s.judge.mean != null);
    const errors = allStages.reduce((n, s) => n + (s.judge_errors || []).length, 0);
    const completed = allStages.reduce((n, s) => n + s.completed, 0);
    const total = allStages.reduce((n, s) => n + s.total, 0);
    const sum = DATA.summary || {};
    const gate = sum.gate || {};
    const sev = sum.severity || {};
    const tiles = [
      ["runs", String(DATA.runs.length), ""],
      ["rows dispatched", `${completed}/${total}`, ""],
      ["stages judged", `${judged.length}/${allStages.length}`, ""],
      ["gate failed", String(gate.failed || 0), gate.failed ? "low" : "high"],
      ["blocking findings", String(sev.blocking || 0), sev.blocking ? "low" : "high"],
      ["judge errors", String(errors), errors ? "low" : ""],
    ];
    const cells = tiles.map(([label, value, cls]) => (
      `<div class="stat"><div class="label">${escapeHtml(label)}</div>` +
      `<div class="value ${cls === "low" ? "bad" : cls === "high" ? "good" : ""}">${escapeHtml(value)}</div></div>`
    )).join("");
    return `<section class="card"><div class="stats">${cells}</div></section>`;
  }

  function renderIndex() {
    const rows = DATA.runs.map((run) => {
      const s = runStats(run);
      const judgeText = s.judgeMean != null ? s.judgeMean.toFixed(1) : "--";
      const checksText = s.checksMean != null ? s.checksMean.toFixed(1) : "n/a";
      const wf = run.workflow || "--";
      const ds = run.dataset_id || "--";
      return `<tr data-search="${escapeHtml(run.run_id)} ${escapeHtml(wf)} ${escapeHtml(ds)}">
        <td data-sort="${escapeHtml(run.run_id)}"><a href="#/run/${encodeURIComponent(run.run_id)}">${escapeHtml(run.run_id)}</a></td>
        <td data-sort="${escapeHtml(wf)}">${pill(wf, "flat")}</td>
        <td data-sort="${escapeHtml(ds)}"><span class="muted">${escapeHtml(ds)}</span></td>
        <td data-sort="${s.nStages}">${s.nStages}</td>
        <td data-sort="${s.judgeMean ?? ""}">${pill(judgeText, band(s.judgeMean))}</td>
        <td data-sort="${s.checksMean ?? ""}">${pill(checksText, band(s.checksMean))}</td>
        <td data-sort="${s.total ? s.completed / s.total : 0}">${s.completed}/${s.total}</td></tr>`;
    }).join("") || '<tr><td colspan="7">no runs yet</td></tr>';

    const runsTable = `<section class="card"><h2>Runs</h2>
      <div class="controls"><input type="search" id="runs-search" placeholder="search runs…" aria-label="search runs">
      <span class="count" id="runs-count">showing ${DATA.runs.length} of ${DATA.runs.length}</span></div>
      <div class="tablewrap"><table id="runs-table">
      <thead><tr><th>run${info("run")}</th><th>workflow${info("workflow")}</th>
      <th>dataset${info("dataset")}</th><th>stages${info("stages")}</th>
      <th>judge (avg)${info("judgeAvg")}</th><th>checks (avg)${info("checksAvg")}</th>
      <th>completed${info("completed")}</th></tr></thead>
      <tbody>${rows}</tbody></table></div></section>`;

    const hero = `<div class="hero">
      <h1>Eval Report</h1>
      <p class="sub">Judge and checks scores, computed by score.py, read straight off stored JSON — nothing recomputed here.</p></div>`;

    // Metrics and charts FIRST — the run table is the detail you drill into
    // once a number has told you where to look, not the thing you scan first.
    mount(`${hero}${warningsHtml()}${overviewHtml()}${trendSection()}${runsTable}`);

    const table = document.getElementById("runs-table");
    if (table.tBodies[0].rows.length && DATA.runs.length) {
      makeSortable(table);
      makeSearchable(document.getElementById("runs-search"), table, document.getElementById("runs-count"));
    }
  }

  // ── trend: judge mean per stage, across runs, oldest first ──────────

  function trendSection() {
    const byStage = {};
    for (const run of [...DATA.runs].reverse()) { // run ids are newest-first
      for (const [stage, facts] of Object.entries(run.stages)) {
        if (facts.judge && facts.judge.mean != null) {
          (byStage[stage] = byStage[stage] || []).push([run.run_id, facts.judge.mean]);
        }
      }
    }
    const stages = Object.keys(byStage).sort();
    if (!stages.length) {
      return '<section class="card"><h2>Trend (judge mean)</h2><p class="muted">no judged runs yet</p></section>';
    }
    const legend = stages.map((s, i) => (
      `<span class="legend-item"><i style="background:${PALETTE[i % PALETTE.length]}"></i>${escapeHtml(s)}</span>`
    )).join("");
    return `<section class="card"><h2>Trend (judge mean)</h2><div class="legend">${legend}</div>${trendSvg(byStage, stages)}</section>`;
  }

  // Run ids are `YYMMDD-HHMMSS-<dataset>` (store.new_run_id), so the run
  // sequence already carries its own clock — no extra field needed.
  function runTimeLabel(runId, withDate) {
    const m = /^(\d{2})(\d{2})(\d{2})-(\d{2})(\d{2})/.exec(runId || "");
    if (!m) return "";
    const [, , mo, d, hh, mm] = m;
    return withDate ? `${d}/${mo} ${hh}:${mm}` : `${hh}:${mm}`;
  }

  function trendSvg(byStage, stages) {
    // Compact by design: 92px of plot, a 0-100 scale implied by two hairline
    // gridlines rather than a labelled axis, and no dot unless a series has
    // few enough points for one to mean anything. The chart answers "is this
    // going up or down" — the exact numbers live in the table below it.
    const W = 960, H = 168, padL = 34, padB = 34, plotW = W - padL - 14, plotH = H - padB - 14;
    const xy = (i, total, value) => {
      const step = plotW / Math.max(1, total - 1);
      const x = padL + (total > 1 ? i * step : plotW / 2);
      const y = 10 + plotH - (Math.max(0, Math.min(100, value)) / 100) * plotH;
      return [x, y];
    };

    let grid = "";
    for (const pct of [0, 50, 100]) {
      const y = (10 + plotH - (pct / 100) * plotH).toFixed(1);
      grid += `<line x1="${padL}" y1="${y}" x2="${W - 14}" y2="${y}" class="grid"/>`;
      grid += `<text x="${padL - 8}" y="${Number(y) + 4}" class="axis-label">${pct}</text>`;
    }

    // X labels come from the LONGEST series (every run that stage appears in)
    // and are thinned so they never collide; the first and last are always
    // kept so the window the chart covers is always readable.
    const axisRuns = stages.reduce((best, st) =>
      byStage[st].length > best.length ? byStage[st] : best, byStage[stages[0]]);
    const n = axisRuns.length;
    const every = Math.max(1, Math.ceil(n / 8));
    const spanDays = new Set(axisRuns.map(([id]) => (id || "").slice(0, 6))).size > 1;
    let xAxis = "";
    axisRuns.forEach(([runId], idx) => {
      if (idx !== 0 && idx !== n - 1 && idx % every !== 0) return;
      const [x] = xy(idx, n, 0);
      const anchor = idx === 0 ? "start" : idx === n - 1 ? "end" : "middle";
      const label = runTimeLabel(runId, spanDays);
      if (!label) return;
      xAxis += `<text x="${x.toFixed(1)}" y="${H - 6}" class="axis-label x" ` +
        `text-anchor="${anchor}">${escapeHtml(label)}</text>`;
    });

    let series = "";
    stages.forEach((stage, i) => {
      const colour = PALETTE[i % PALETTE.length];
      const points = byStage[stage];
      const coords = points.map((p, idx) => xy(idx, points.length, p[1]).join(",")).join(" ");
      // Dots only when they are readable; past ~12 points they merge into the
      // line and just add noise. The <title> tooltips go with them.
      const dots = points.length <= 12 ? points.map(([runId, value], idx) => {
        const [x, y] = xy(idx, points.length, value);
        return `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="2.5" fill="${colour}" class="dot">` +
          `<title>${escapeHtml(stage)} — ${escapeHtml(runId)}: ${value.toFixed(1)}</title></circle>`;
      }).join("") : "";
      series += `<polyline points="${coords}" fill="none" stroke="${colour}" ` +
        `stroke-width="1.75" stroke-linejoin="round" stroke-linecap="round"/>${dots}`;
    });

    // No preserveAspectRatio override: uniform scaling keeps the axis labels
    // and dots round. A wide viewBox is what makes it span the card.
    return `<svg class="trend" viewBox="0 0 ${W} ${H}" role="img"
      aria-label="judge mean per stage across runs">${grid}${xAxis}${series}</svg>`;
  }

  // ── run detail: this run's stage table ───────────────────────────────

  function renderRun(runId) {
    const run = findRun(runId);
    if (!run) return mount(`<p class="crumbs"><a href="#/">Runs</a></p><p>run not found: ${escapeHtml(runId)}</p>`);

    const rows = Object.entries(run.stages).map(([stage, facts]) => {
      const judgeText = facts.judge && facts.judge.mean != null ? `${facts.judge.mean.toFixed(1)} (n=${facts.judge.n})` : "--";
      const href = `#/run/${encodeURIComponent(run.run_id)}/${encodeURIComponent(stage)}`;
      return `<tr><td data-sort="${escapeHtml(stage)}"><a href="${href}">${escapeHtml(stage)}</a></td>
        <td data-sort="${(facts.judge && facts.judge.mean) ?? ""}">${pill(judgeText, band(facts.judge && facts.judge.mean))}</td>
        <td data-sort="${(facts.checks && facts.checks.pct) ?? ""}">${checksCell(facts.checks)}</td>
        <td data-sort="${facts.total ? facts.completed / facts.total : 0}">${facts.completed}/${facts.total}</td></tr>`;
    }).join("");

    // Footer totals come from Python (run.totals) — the same numbers the index
    // row shows, never re-averaged here.
    const t = run.totals || {};
    const gate = t.gate_failed
      ? ` <span class="pill low">GATE: ${t.gate_failed} stage(s) failed</span>` : "";
    const foot = `<tr class="totals">
      <td><strong>all stages</strong>${gate}</td>
      <td>${pill(t.judge_mean != null ? `${t.judge_mean.toFixed(1)} (${t.judge_stages}/${t.stages})` : "--", band(t.judge_mean))}</td>
      <td>${pill(t.checks_mean != null ? `${t.checks_mean.toFixed(1)} (${t.checks_stages}/${t.stages})` : "--", band(t.checks_mean))}</td>
      <td>${t.completed}/${t.total}</td></tr>`;

    const meta = [run.workflow, run.dataset_id].filter(Boolean).map(escapeHtml).join(" · ");
    mount(`<p class="crumbs"><a href="#/">Runs</a> / ${escapeHtml(run.run_id)}</p>
      <h1>${escapeHtml(run.run_id)}</h1>
      ${meta ? `<p class="muted" style="margin-top:-8px">${meta}</p>` : ""}
      <section class="card"><div class="tablewrap"><table id="stage-table">
      <thead><tr><th>stage${info("stage")}</th><th>judge${info("judge")}</th>
      <th>checks${info("checks")}</th><th>completed${info("completed")}</th></tr></thead>
      <tbody>${rows}</tbody><tfoot>${foot}</tfoot></table></div></section>`);

    makeSortable(document.getElementById("stage-table"));
  }

  function renderStage(runId, stage) {
    const run = findRun(runId);
    const facts = run && run.stages[stage];
    if (!facts) {
      return mount(`<p class="crumbs"><a href="#/">Runs</a></p><p>stage not found: ${escapeHtml(stage)}</p>`);
    }
    const runHref = `#/run/${encodeURIComponent(runId)}`;
    const rowsHtml = facts.rows.map((row) => rowDetail(row, facts)).join("") || '<p class="muted">no rows</p>';
    const search = facts.rows.length > 1
      ? `<div class="controls"><input type="search" id="rows-search" placeholder="search rows…" aria-label="search rows">
         <span class="count" id="rows-count">showing ${facts.rows.length} of ${facts.rows.length}</span></div>`
      : "";

    // The artifact opens in a real tab: the iframe is sandboxed and boxed
    // into the page, which is fine for a glance and useless for actually
    // using a 35KB prototype.
    const openLink = facts.artifact_href
      ? ` <a class="open-artifact" href="${escapeHtml(facts.artifact_href)}" target="_blank" rel="noopener">open ${escapeHtml(facts.artifact_href.split("/").pop())} ↗</a>`
      : "";
    mount(`<p class="crumbs"><a href="#/">Runs</a> / <a href="${runHref}">${escapeHtml(runId)}</a> / ${escapeHtml(stage)}</p>
      <h1>${escapeHtml(stage)} <span class="muted" style="font-size:14px">— ${facts.completed}/${facts.total} completed</span>${openLink}</h1>
      ${checksBanner(facts)}${judgeErrorsHtml(facts)}${advisorHtml(facts)}${adviceHtml(facts)}${search}<div id="rows-list">${rowsHtml}</div>`);

    const searchInput = document.getElementById("rows-search");
    if (searchInput) {
      searchInput.addEventListener("input", () => {
        const needle = searchInput.value.trim().toLowerCase();
        const items = document.querySelectorAll("#rows-list > .row-detail");
        let shown = 0;
        items.forEach((el) => {
          const match = !needle || el.textContent.toLowerCase().indexOf(needle) !== -1;
          el.classList.toggle("hidden", !match);
          if (match) shown++;
        });
        document.getElementById("rows-count").textContent = `showing ${shown} of ${items.length}`;
      });
    }

    // iframe srcdoc is set via the DOM property, not an HTML attribute string —
    // the content never has to survive attribute-escaping this way.
    for (const row of facts.rows) {
      for (const [name, content] of Object.entries(row.artifacts || {})) {
        if (!/\.html?$/i.test(name)) continue;
        const el = document.getElementById(`iframe-${row.row_id}-${name}`);
        if (el) el.srcdoc = content;
      }
      if (/^\s*(<!doctype html|<html)/i.test(row.response || "")) {
        const el = document.getElementById(`iframe-${row.row_id}-response`);
        if (el) el.srcdoc = row.response;
      }
    }
  }

  // ── advisor: cluster judge weaknesses/strengths across rows ──────────
  // Exact-text clustering only — no fuzzy NLP, no synthesis, no proposed
  // edit. This counts and sorts what the judge already said; you still read
  // it and edit AGENT.md yourself. (spec explicitly excludes an auto-apply
  // advisor — this is the observational half only.)

  function tally(items) {
    const counts = new Map();
    for (const { text, rowId } of items) {
      if (!text) continue;
      const entry = counts.get(text) || { text, rowIds: [] };
      entry.rowIds.push(rowId);
      counts.set(text, entry);
    }
    return [...counts.values()].sort((a, b) => b.rowIds.length - a.rowIds.length);
  }

  function adviceList(entries) {
    return entries.map(({ text, rowIds }) => (
      `<li><span class="pill flat">${rowIds.length}</span> ${escapeHtml(text)}
        <span class="muted small">(${rowIds.map(escapeHtml).join(", ")})</span></li>`
    )).join("");
  }

  function adviceHtml(facts) {
    const weaknesses = tally(facts.rows.flatMap((r) => (
      (r.judge && r.judge.weaknesses || []).map((text) => ({ text, rowId: r.row_id }))
    )));
    const strengths = tally(facts.rows.flatMap((r) => (
      (r.judge && r.judge.strengths || []).map((text) => ({ text, rowId: r.row_id }))
    )));
    if (!weaknesses.length && !strengths.length) return "";

    const weakBlock = weaknesses.length
      ? `<h4>Weaknesses <span class="muted small">— widest first, what to fix</span></h4><ul>${adviceList(weaknesses)}</ul>`
      : "";
    const strongBlock = strengths.length
      ? `<h4>Strengths <span class="muted small">— what an edit must not break</span></h4><ul>${adviceList(strengths)}</ul>`
      : "";
    return `<section class="card advice"><h2>Advice</h2>${weakBlock}${strongBlock}</section>`;
  }

  // ── the paid advisor: one real model call proposing a prompt edit,
  // opt-in via `eval score <run> --stage X --advise`. Separate from the
  // free clustering card above — this is model prose, not a tally.

  // Priority wording, not a bare number. `advisory_score` is 0-100 where 0
  // means MAY and 100 means MUST, so printing "ADD 80" made the reader do the
  // mapping in their head and told them nothing at a glance.
  const MUST_AT = 70, SHOULD_AT = 30;

  function priority(score) {
    if (score >= MUST_AT) return { label: "MUST", cls: "low" };
    if (score >= SHOULD_AT) return { label: "SHOULD", cls: "mid" };
    return { label: "MAY", cls: "flat" };
  }

  function suggestionLi(e, extra) {
    const p = priority(e.advisory_score || 0);
    const kind = e.kind === "remove" ? "REMOVE" : "ADD";
    const cat = e.category
      ? ` <span class="pill flat">${escapeHtml(e.category)}</span>` : "";
    return `<li>
      <span class="pill ${p.cls}">${kind} — ${p.label}</span>${cat}${extra || ""}
      <div class="advice-desc">${escapeHtml(e.description)}</div></li>`;
  }

  function advisorHtml(facts) {
    const advice = facts.advice;
    if (!advice) return "";
    if (advice.errored) {
      return `<section class="card warn"><h2>Advisor</h2>
        <p class="muted">the advisor call failed: ${escapeHtml(advice.error_reason || "unknown error")}</p></section>`;
    }
    // ONE flat list; `action` is a field on each suggestion, not a separate
    // array. Legacy `add`/`remove` arrays are folded in so advice stored
    // before the schema changed still renders instead of reading "no advice"
    // — which is exactly the bug this function had when it tested
    // `advice.text`, a field the advisor had already stopped producing.
    const items = (advice.advice || []).slice();
    for (const kind of ["add", "remove"]) {
      for (const e of advice[kind] || []) items.push({ action: kind, ...e });
    }
    if (!items.length) {
      const legacy = advice.text
        ? `<pre>${escapeHtml(advice.text)}</pre>`
        : `<p class="muted">${escapeHtml(advice.note || "no suggestions returned")}</p>`;
      return `<section class="card"><h2>Advisor</h2>${legacy}</section>`;
    }
    items.sort((a, b) => (b.advisory_score || 0) - (a.advisory_score || 0));
    return `<section class="card advice"><h2>Advisor — proposed prompt edits</h2>
      <p class="muted small">Strongest first. MUST/SHOULD/MAY is the advisor's own
      confidence, not a quality score.</p>
      <ul class="advice-list">${items.map((e) => suggestionLi(e)).join("")}</ul></section>`;
  }

  function judgeErrorsHtml(facts) {
    const errors = facts.judge_errors || [];
    if (!errors.length) return "";
    const items = errors.map((e) => (
      `<li><code>${escapeHtml(e.row_id)}</code>: ${escapeHtml(e.reason)}</li>`
    )).join("");
    return `<section class="card warn"><h2>Judge errors (${errors.length})</h2>
      <p class="muted">These rows were judged but dropped — "judge --" above means this, not "never scored".</p>
      <ul>${items}</ul></section>`;
  }

  const ORIGIN_BAND = { dispatched: "flat", seeded: "mid", replayed: "mid" };

  function rowDetail(row, facts) {
    const response = row.response || "";
    const excerpt = escapeHtml(response.slice(0, 400));
    const fullToggle = response.length > 400
      ? `<details><summary class="muted small">show full response (${response.length} chars)</summary>
           <pre>${escapeHtml(response)}</pre></details>`
      : "";

    let judgeHtml = "";
    if (row.judge) {
      const subScores = Object.entries(row.judge.sub_scores || {}).map(([k, v]) => (
        `<span class="pill ${band(v)}" title="${escapeHtml(k)}">${escapeHtml(k)} ${v}</span>`
      )).join(" ");
      const tokens = (row.judge.tokens_in || row.judge.tokens_out)
        ? `<span class="muted small">judge tokens: in=${row.judge.tokens_in} out=${row.judge.tokens_out}</span>` : "";
      // The score beside this is the JUDGE's alone — checks are never folded
      // into it (R-03). Both facts, side by side, is the honest reading.
      const checksOverride = row.judge.checks_failed
        ? `<p class="muted small">checks FAILED on this row — the score beside it rates content only; this deliverable does not render</p>` : "";
      judgeHtml = `<div class="judge-block"><p>${pill(row.judge.score.toFixed(1), band(row.judge.score))} ${subScores}</p>
        ${checksOverride}<p class="muted">${escapeHtml((row.judge.rationale || "").slice(0, 300))}</p>${tokens}</div>`;
    }
    const findingHtml = row.checks_summary ? `<p class="muted small">checks: ${escapeHtml(row.checks_summary)}</p>` : "";
    // Files this stage was SEEDED with are named, not rendered — they belong
    // to the phase that produced them and are one click away there.
    const inheritedHtml = (row.inherited || []).length
      ? `<p class="muted small">seeded from upstream: ${row.inherited.map(escapeHtml).join(", ")}</p>` : "";
    const artifactsHtml = Object.entries(row.artifacts || {}).map(([name, content]) => (
      /\.html?$/i.test(name)
        ? `<details class="artifact"><summary>preview: ${escapeHtml(name)}</summary>
             <iframe id="iframe-${row.row_id}-${name}" sandbox loading="lazy"></iframe></details>`
        : `<details class="artifact"><summary>${escapeHtml(name)}</summary><pre>${escapeHtml(content.slice(0, 3000))}</pre></details>`
    )).join("");
    // The response itself can BE the HTML (seeded rows, text-only agents) —
    // artifacts only ever come from a dispatched row's sandbox snapshot, so
    // without this a response that's real HTML but has no matching artifact
    // file got no preview at all.
    const responseIsHtml = /^\s*(<!doctype html|<html)/i.test(response);
    const responsePreview = responseIsHtml
      ? `<details class="artifact"><summary>preview: response</summary>
           <iframe id="iframe-${row.row_id}-response" sandbox loading="lazy"></iframe></details>`
      : "";

    const badges = `${pill(row.origin, ORIGIN_BAND[row.origin] || "flat")}` +
      (row.errored ? ` ${pill("errored", "low")}` : "");

    return `<div class="row-detail${row.errored ? " errored" : ""}">
      <h4>${escapeHtml(row.row_id)} ${badges}</h4>
      ${judgeHtml}${findingHtml}${inheritedHtml}<pre>${excerpt}</pre>${fullToggle}${responsePreview}${artifactsHtml}</div>`;
  }
})();
